'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// Caret zero rules
assert.equal(satisfies('0.3.9', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('1.9.0', '^1.2.0'), true);

// Backtracking: a@2 needs c@2 which conflicts with b's c@1 constraint; must undo a@2's constraints
const r1 = {
  a: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
  b: { '1.0.0': { c: '1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
};
assert.deepEqual(resolve(r1, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// Stale constraint leak: x@2 adds y<1 constraint then fails via z; after undo, y@1 must be allowed
const r2 = {
  x: { '2.0.0': { y: '<1.0.0', z: '2.0.0' }, '1.0.0': {} },
  y: { '1.0.0': {}, '0.5.0': {} },
  z: { '1.0.0': {} },
};
assert.deepEqual(resolve(r2, { x: '*', y: '*' }), { x: '1.0.0', y: '1.0.0' });

// Cycle
const r3 = { p: { '1.0.0': { q: '^1.0.0' } }, q: { '1.0.0': { p: '1.0.0' } } };
assert.deepEqual(resolve(r3, { p: '*' }), { p: '1.0.0', q: '1.0.0' });

// Missing package / unsatisfiable
assert.equal(resolve({}, { nope: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Long chain with backtracking at the end
const N = 20000;
const reg = {};
for (let i = 0; i < N; i += 1) reg[`n${i}`] = { '1.0.0': i + 1 < N ? { [`n${i + 1}`]: '*' } : {} };
const res = resolve(reg, { n0: '*' });
assert.equal(Object.keys(res).length, N);

// Eager validation of unreachable entries
assert.throws(() => resolve({ u: { 'bad': {} } }, {}), TypeError);
assert.throws(() => resolve({ u: { '1.0.0': { v: '' } } }, {}), TypeError);

// __proto__ name
const r4 = JSON.parse('{"__proto__": {"1.0.0": {}}}');
assert.deepEqual(Object.keys(resolve(r4, JSON.parse('{"__proto__": "*"}'))), ['__proto__']);
console.log('smoke ok');
